export class PersonalInfoModel {
    constructor(events) {
        this.events = events;
    }
    set paymentType(val) {
        this._paymentType = val;
        this.events.emit('items: changed');
    }
    set address(val) {
        this._address = val;
        this.events.emit('items: changed');
    }
    set email(val) {
        this._email = val;
        this.events.emit('items: changed');
    }
    set phone(val) {
        this._phone = val;
        this.events.emit('items: changed');
    }
    get paymentType() {
        return this._paymentType;
    }
    get address() {
        return this._address;
    }
    get email() {
        return this._email;
    }
    get phone() {
        return this._phone;
    }
}
